package net.officefloor.hq.app.pool;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The pools by sheet, and their members. Each is kept with the sheet's today when it was added (added_on). */
@Repository
public class PoolRepository {

    private static final RowMapper<Pool> ROW = (rs, i) -> new Pool(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getString("name"), rs.getString("added_by"));

    private final JdbcTemplate jdbc;

    public PoolRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's pools in the order they were added (those added by the end of the day, when one is given). */
    public List<Pool> list(String sheetId, LocalDate end) {
        return end == null
                ? jdbc.query("SELECT * FROM pool WHERE sheet_id = ? ORDER BY id", ROW, sheetId)
                : jdbc.query("SELECT * FROM pool WHERE sheet_id = ? AND (added_on IS NULL OR added_on <= ?) "
                        + "ORDER BY id", ROW, sheetId, end);
    }

    /** The pool on this sheet with this name, or null when absent. */
    public Pool find(String sheetId, String name) {
        return jdbc.query("SELECT * FROM pool WHERE sheet_id = ? AND name = ?", ROW, sheetId, name).stream()
                .findFirst().orElse(null);
    }

    /** The pool on this sheet with this id, or null when absent. */
    public Pool find(String sheetId, long id) {
        return jdbc.query("SELECT * FROM pool WHERE sheet_id = ? AND id = ?", ROW, sheetId, id).stream()
                .findFirst().orElse(null);
    }

    public Pool add(String sheetId, PoolInput input) {
        jdbc.update("INSERT INTO pool (sheet_id, name, added_by, added_on) "
                + "VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", sheetId, input.name(), input.user(),
                sheetId);
        return find(sheetId, input.name());
    }

    public boolean isMember(Pool pool, long personId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool_member WHERE pool_id = ? AND person_id = ?",
                Integer.class, pool.id(), personId);
        return n != null && n > 0;
    }

    /** The pool this pool is a member of, or null when it is a member of none. */
    public Pool parent(Pool pool) {
        return jdbc.query("SELECT p.* FROM pool p JOIN pool_member m ON m.pool_id = p.id WHERE m.member_pool_id = ?",
                ROW, pool.id()).stream().findFirst().orElse(null);
    }

    /** The pools that are members of this pool. */
    public List<Pool> children(Pool pool) {
        return jdbc.query("SELECT p.* FROM pool p JOIN pool_member m ON m.member_pool_id = p.id WHERE m.pool_id = ? "
                + "ORDER BY m.id", ROW, pool.id());
    }

    public PoolMember addMember(Pool pool, Pool member, PoolMemberInput input) {
        jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, member_pool_id, share, added_by, added_on, from_date, "
                + "to_date) VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)", pool.sheetId(),
                pool.id(), member.id(), input.share(), input.user(), pool.sheetId(), input.from(), input.to());
        return new PoolMember(pool.id(), pool.sheetId(), pool.name(), 0, member.name(), input.share(), input.user(),
                member.id(), input.from(), input.to());
    }

    public PoolMember addMember(Pool pool, Person person, PoolMemberInput input) {
        jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, person_id, share, added_by, added_on, from_date, "
                + "to_date) VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)", pool.sheetId(),
                pool.id(), person.id(), input.share(), input.user(), pool.sheetId(), input.from(), input.to());
        return new PoolMember(pool.id(), pool.sheetId(), pool.name(), person.id(), person.name(), input.share(),
                input.user(), null, input.from(), input.to());
    }

    /** The pool's members in the order they were added (those added by the end of the day, when one is given),
     *  named by the person's id (or the member pool's id) only: the caller names them. */
    public List<PoolMember> members(Pool pool, LocalDate end) {
        RowMapper<PoolMember> row = (rs, i) -> new PoolMember(pool.id(), pool.sheetId(), pool.name(),
                rs.getLong("person_id"), null, rs.getBigDecimal("share").setScale(2), rs.getString("added_by"),
                rs.getObject("member_pool_id", Long.class), rs.getObject("from_date", LocalDate.class),
                rs.getObject("to_date", LocalDate.class));
        return end == null
                ? jdbc.query("SELECT * FROM pool_member WHERE pool_id = ? ORDER BY id", row, pool.id())
                : jdbc.query("SELECT * FROM pool_member WHERE pool_id = ? AND (added_on IS NULL OR added_on <= ?) "
                        + "ORDER BY id", row, pool.id(), end);
    }

    /** Drop the person from every pool they are a member of. */
    public void drop(String sheetId, long personId) {
        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ?", sheetId, personId);
    }

    /** On merging one person into another: the first's pool memberships move to the other, their share added to the
     *  other's where the other is already a member. */
    public void merge(String sheetId, long fromId, long intoId) {
        jdbc.update("UPDATE pool_member m SET share = share + (SELECT f.share FROM pool_member f WHERE f.pool_id = m.pool_id "
                + "AND f.person_id = ?) WHERE sheet_id = ? AND person_id = ? AND EXISTS (SELECT 1 FROM pool_member f "
                + "WHERE f.pool_id = m.pool_id AND f.person_id = ?)", fromId, sheetId, intoId, fromId);
        jdbc.update("DELETE FROM pool_member m WHERE sheet_id = ? AND person_id = ? AND EXISTS (SELECT 1 FROM pool_member i "
                + "WHERE i.pool_id = m.pool_id AND i.person_id = ?)", sheetId, fromId, intoId);
        jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** A pool as the screen shows it: its members in the order they were added, the total of their shares (a member
 *  retired by the date counts their share as given) and whether it is balanced (the total is exactly 100.00). */
public record PoolResponse(long id, String name, List<Member> members, String totalShare, boolean balanced) {

    /** A member: the person (or, for a member pool, null and the pool's id in poolId), their name, their share,
     *  whether they are retired by the date, and their cut of the pool's pot ('' when the pool is unbalanced or there
     *  is no pot, or when the membership's dates leave them out), the membership's from- and to-dates ('' when open)
     *  and whether those dates leave them out on the date. */
    public record Member(Long personId, String name, String share, boolean retired, String cut, Long poolId,
            String from, String to, boolean outside) {
    }

    /** This member pool's cut, or null when it is not a member here or has no cut. */
    public BigDecimal cutOf(long memberPoolId) {
        return members.stream().filter(m -> m.poolId() != null && m.poolId() == memberPoolId && !m.cut().isEmpty())
                .map(m -> new BigDecimal(m.cut())).findFirst().orElse(null);
    }

    private static final BigDecimal FULL = new BigDecimal("100.00");

    /** The pool with its members; retiredFrom gives each person's retirement date (absent: not retired), held the
     *  people with a hold in force on the date, and on is the date it is judged by (null: none retired). When the
     *  pool is balanced and there is a pot (null: none), a retired or held member cuts 0.00 (their share spread over the others) and each other member's
     *  cut is the pot (the sheet's, or for a member pool its cut in the pool above) times their share divided by the
     *  shares of the members with a cut, added up, rounded half to even to two decimals, and the pot less the cuts
     *  goes to the member with the smallest non-zero cut (the latest added on a tie; a member with no cut gets
     *  none, and when no cut is non-zero it goes to the last member with a cut and a share), so the cuts total
     *  exactly the pot; when every member is retired there are no cuts ('' shown). A hold or a retirement leaves the total
     *  share and balance alone. A member whose membership dates do not include the
     *  date is left out entirely: not in the total share, not in the balance, and no cut ('' shown). */
    public static PoolResponse from(Pool pool, List<PoolMember> members, Map<Long, LocalDate> retiredFrom,
            Set<Long> held, LocalDate on, BigDecimal pot) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean[] retired = new boolean[members.size()];
        boolean[] outside = new boolean[members.size()];
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            outside[i] = !m.covers(on);
            if (outside[i]) {
                continue;
            }
            LocalDate from = m.isPool() ? null : retiredFrom.get(m.personId());
            retired[i] = on != null && from != null && !from.isAfter(on);
            total = total.add(m.share());
        }
        boolean balanced = total.compareTo(FULL) == 0;
        boolean[] noCut = new boolean[members.size()];
        boolean allRetired = true;
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            noCut[i] = outside[i] || retired[i] || (!m.isPool() && held.contains(m.personId()));
            if (!outside[i] && !retired[i]) {
                allRetired = false;
            }
        }
        BigDecimal[] cuts = balanced && pot != null && !allRetired ? cuts(members, noCut, pot) : null;
        List<Member> shown = new ArrayList<>();
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            shown.add(new Member(m.isPool() ? null : m.personId(), m.name(), m.share().toPlainString(), retired[i],
                    cuts != null && !outside[i] ? cuts[i].toPlainString() : "", m.memberPoolId(), date(m.from()),
                    date(m.to()), outside[i]));
        }
        return new PoolResponse(pool.id(), pool.name(), shown, total.toPlainString(), balanced);
    }

    public static PoolResponse from(Pool pool, List<PoolMember> members, LocalDate on) {
        return from(pool, members, Map.of(), Set.of(), on, null);
    }

    private static String date(LocalDate d) {
        return d == null ? "" : d.toString();
    }

    private static BigDecimal[] cuts(List<PoolMember> members, boolean[] noCut, BigDecimal pot) {
        BigDecimal[] cuts = new BigDecimal[members.size()];
        BigDecimal shares = BigDecimal.ZERO;
        for (int i = 0; i < members.size(); i++) {
            if (!noCut[i]) {
                shares = shares.add(members.get(i).share());
            }
        }
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int smallest = -1;
        int last = -1;
        for (int i = 0; i < members.size(); i++) {
            BigDecimal share = members.get(i).share();
            cuts[i] = noCut[i] ? BigDecimal.ZERO.setScale(2)
                    : pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN);
            sum = sum.add(cuts[i]);
            if (noCut[i]) {
                continue;
            }
            if (share.signum() != 0) {
                last = i;
            }
            if (cuts[i].signum() != 0 && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
                smallest = i;
            }
        }
        int to = smallest >= 0 ? smallest : last;
        if (to >= 0) {
            cuts[to] = cuts[to].add(pot.subtract(sum));
        }
        return cuts;
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's pools in the order they were added, with their members, total share and whether balanced; a member
 *  retired by the sheet's today (or the as-of date, when one is given) cuts 0.00, their share still counted toward the total
 *  and spread over the members with a cut (no cuts at all when every member is retired); each member of a balanced pool
 *  shows their cut of the pool's pot (when there is one). A pool that is a member of none has the sheet's pot (as it stood
 *  then, given an as-of date); a pool
 *  that is a member of another has its cut there as its pot (none when the pool above has no cuts). A person with a
 *  hold in force on that date cuts 0.00, their share spread over the members with a cut. A member whose membership
 *  dates do not include that date is left out: no share in the total and no cut. */
public class RespondWithPools {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, PoolRepository repository,
            PersonRepository people, SheetRepository sheets, SettingRepository settings,
            ObjectResponse<List<PoolResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        LocalDate on = end != null ? end : sheets.today(id);
        List<Person> persons = end != null ? people.listAsOf(id, end) : people.list(id);
        Map<Long, LocalDate> retiredFrom = new HashMap<>();
        Map<Long, String> names = new HashMap<>();
        Set<Long> held = new HashSet<>();
        BigDecimal pot = end != null ? settings.potAsOf(id, end) : settings.pot(id);
        for (Person p : persons) {
            names.put(p.id(), p.name());
            if (p.retiredFrom() != null) {
                retiredFrom.put(p.id(), p.retiredFrom());
            }
            if (on != null && p.holds().covers(on)) {
                held.add(p.id());
            }
        }
        List<Pool> pools = repository.list(id, end);
        Map<Long, String> poolNames = new HashMap<>();
        pools.forEach(p -> poolNames.put(p.id(), p.name()));
        Map<Long, List<PoolMember>> members = new HashMap<>();
        Map<Long, Pool> parents = new HashMap<>();
        for (Pool pool : pools) {
            List<PoolMember> named = repository.members(pool, end).stream()
                    .filter(m -> m.isPool() ? poolNames.containsKey(m.memberPoolId())
                            : names.containsKey(m.personId()))
                    .map(m -> m.named(m.isPool() ? poolNames.get(m.memberPoolId()) : names.get(m.personId())))
                    .toList();
            members.put(pool.id(), named);
            named.stream().filter(PoolMember::isPool).forEach(m -> parents.put(m.memberPoolId(), pool));
        }
        Map<Long, PoolResponse> shown = new HashMap<>();
        response.send(pools.stream()
                .map(pool -> shown(pool, members, parents, retiredFrom, held, on, pot, shown)).toList());
    }

    /** The pool as shown, its pot the sheet's or its cut in the pool above (worked out first). */
    private static PoolResponse shown(Pool pool, Map<Long, List<PoolMember>> members, Map<Long, Pool> parents,
            Map<Long, LocalDate> retiredFrom, Set<Long> held, LocalDate on, BigDecimal sheetPot, Map<Long, PoolResponse> shown) {
        PoolResponse done = shown.get(pool.id());
        if (done != null) {
            return done;
        }
        Pool above = parents.get(pool.id());
        BigDecimal pot = above == null ? sheetPot
                : shown(above, members, parents, retiredFrom, held, on, sheetPot, shown).cutOf(pool.id());
        PoolResponse r = PoolResponse.from(pool, members.get(pool.id()), retiredFrom, held, on, pot);
        shown.put(pool.id(), r);
        return r;
    }
}
