import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user, a person or a pool, and a share of at
 *  most two decimals, more than 0.00 and at most 100.00, and from- and to-dates (each optional) that are dates, the
 *  to-date not before the from-date. */
public class ValidatePoolMember {

    private static final BigDecimal MAX = new BigDecimal("100.00");

    public void validate(@RequestBody PoolMemberRequest request, Out<PoolMemberInput> body)
            throws InvalidPoolException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPoolException("Sign in before adding a pool member.");
        }
        if ((request.personId() == null) == (request.memberPoolId() == null)) {
            throw new InvalidPoolException("Choose the person or pool to add.");
        }
        String raw = request.share() == null ? "" : request.share().trim();
        if (!raw.matches("\\d+(\\.\\d{1,2})?")) {
            throw new InvalidPoolException("Give the share as a percent with at most two decimals.");
        }
        BigDecimal share = new BigDecimal(raw).setScale(2);
        if (share.signum() <= 0 || share.compareTo(MAX) > 0) {
            throw new InvalidPoolException("A share is more than 0.00 and at most 100.00.");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidPoolException("The to-date cannot be before the from-date.");
        }
        body.set(new PoolMemberInput(request.user().trim(), request.personId(), share, request.memberPoolId(), from,
                to));
    }

    /** The date as typed, or null when blank. */
    private static LocalDate date(String text, String which) throws InvalidPoolException {
        String raw = text == null ? "" : text.trim();
        if (raw.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidPoolException("Give the " + which + "-date as a date (yyyy-mm-dd).");
        }
    }
}
package net.officefloor.hq.app.pool;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Store the member, refusing an unknown pool or person, or a person already in the pool. A member pool is refused
 *  when it is already a member of a pool, when it is the pool itself or contains it through any chain, or when the
 *  chain of pools would be more than three deep. */
public class SavePoolMember {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") String poolId,
            @Val PoolMemberInput input, PeriodRepository periods, PoolRepository repository, PersonRepository people,
            Out<PoolMember> member) throws InvalidPoolException {
        String id = sheetId.trim();
        periods.lockSheet(id);
        Pool pool;
        try {
            pool = repository.find(id, Long.parseLong(poolId.trim()));
        } catch (NumberFormatException e) {
            pool = null;
        }
        if (pool == null) {
            throw new InvalidPoolException("No pool " + poolId + " on this sheet.");
        }
        if (input.memberPoolId() != null) {
            member.set(repository.addMember(pool, memberPool(id, pool, input.memberPoolId(), repository), input));
            return;
        }
        Person person = people.find(id, input.personId());
        if (person == null) {
            throw new InvalidPoolException("No person " + input.personId() + " on this sheet.");
        }
        if (repository.isMember(pool, person.id())) {
            throw new InvalidPoolException(person.name() + " is already in " + pool.name() + ".");
        }
        member.set(repository.addMember(pool, person, input));
    }

    private static final int MAX_DEPTH = 3;

    private static Pool memberPool(String sheetId, Pool pool, long memberPoolId, PoolRepository repository)
            throws InvalidPoolException {
        Pool child = repository.find(sheetId, memberPoolId);
        if (child == null) {
            throw new InvalidPoolException("No pool " + memberPoolId + " on this sheet.");
        }
        if (child.id() == pool.id()) {
            throw new InvalidPoolException("A pool cannot be a member of itself.");
        }
        Pool above = repository.parent(child);
        if (above != null) {
            throw new InvalidPoolException(child.name() + " is already a member of " + above.name() + ".");
        }
        int depth = 1;
        for (Pool p = repository.parent(pool); p != null; p = repository.parent(p)) {
            if (p.id() == child.id()) {
                throw new InvalidPoolException(pool.name() + " is already within " + child.name() + ".");
            }
            depth++;
        }
        if (depth + height(child, repository) > MAX_DEPTH) {
            throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep.");
        }
        return child;
    }

    /** How many levels of pools this pool heads, itself included. */
    private static int height(Pool pool, PoolRepository repository) {
        int below = 0;
        for (Pool c : repository.children(pool)) {
            below = Math.max(below, height(c, repository));
        }
        return below + 1;
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A member of a pool with their share percent (more than 0.00, at most 100.00): a person, or another pool
 *  (memberPoolId; personId then 0, and name the pool's name); from and to date the membership (each null when
 *  open, both inclusive). */
public record PoolMember(long poolId, String sheetId, String pool, long personId, String name, BigDecimal share,
        String by, Long memberPoolId, LocalDate from, LocalDate to) {

    public PoolMember(long poolId, String sheetId, String pool, long personId, String name, BigDecimal share,
            String by) {
        this(poolId, sheetId, pool, personId, name, share, by, null, null, null);
    }

    public boolean isPool() {
        return memberPoolId != null;
    }

    /** Whether the membership's dates include this day (always, when there is no day). */
    public boolean covers(LocalDate on) {
        return on == null || ((from == null || !from.isAfter(on)) && (to == null || !to.isBefore(on)));
    }

    /** The same member under another name. */
    public PoolMember named(String name) {
        return new PoolMember(poolId, sheetId, pool, personId, name, share, by, memberPoolId, from, to);
    }
}

