// Playwright config. Tests bind to data-testid only and assert through the UI. The app is already
// running (started by bin/e2e), so no webServer here.
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './specs',
  use: {
    baseURL: process.env.BASE_URL ?? `http://localhost:${process.env.PORT ?? 3000}`,
    // The contract attribute is data-testid — Playwright's default, so no testIdAttribute override
    // needed. Strict awaiting on data-testid presence is the flake guard.
  },
  // Every spec arranges its own data through the screens on a sheet id of its own and reads the
  // audit file filtered by that id, so specs never share data. workers:1 keeps the suite serial
  // against the one shared app, so a failure stays attributable to one spec.
  fullyParallel: false,
  workers: 1,
  reporter: [['list']],
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // Headless Chromium needs its own sandbox off and
        // shared memory in /tmp, or renderer/GPU child processes crash. Harmless elsewhere too.
        launchOptions: { args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] },
      },
    },
  ],
});
# Paste claims: each line name,amount,date,note (the note may end " #<reference>") adds a claim for the named person and opens it, in order; a line
# matching one of the person's claims by date and note updates that DRAFT to its amount and opens it instead (any other status matching is an error). Every line is
# checked first by the claim form's rules (and the name must be on the sheet, and no reference used on the sheet or earlier in the paste); one failing line, or any
# refusal the open button would give, refuses the whole paste, which writes nothing, not even an audit line. Responds with how many lines went through.
validate:
  class: net.officefloor.hq.app.claim.ValidatePaste
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: paste
paste:
  class: net.officefloor.hq.app.claim.PasteClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithPaste
  govern: [ transaction ]

